	if err := fs.Parse(args); err != nil {
		os.Exit(2)
	}
	if *inputPath == "" || *store == "" {
		fmt.Fprintln(os.Stderr, "usage: contractsentinel audit --input <file> --store <dir>")
		os.Exit(2)
	}
	data, err := os.ReadFile(*inputPath)
	if err != nil {
		fail("audit", err)
	}
	artifact, rules, invariants, checks, err := contractsentinel.ParseAuditInput(data)
	if err != nil {
		fail("audit", err)
	}
	report, err := contractsentinel.BuildReport(artifact, rules, invariants, checks)
	if err != nil {
		fail("audit", err)
	}
	if err := contractsentinel.SaveReport(*store, report); err != nil {
		fail("audit", err)
	}
	printReport("audit", report)
}

// runReport reads a saved report by id and prints it.
func runReport(args []string) {
	fs := flag.NewFlagSet("report", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
