423			t.Fatalf("stderr must state the mismatch reason:\n%s", stderr)
424		}
425		assertNoPartialReport(t, stdout)
426		if _, err := os.Stat(store); !os.IsNotExist(err) {
427			t.Fatalf("rejected submission must not create the store directory: %v", err)
428		}
429	}
430	
431	// 拒绝是“提交无效”：stdout 不能把错误记录标成任何一种已知状态后部分输出。
432	func TestCLIAuditImportChecksMismatchHasNoStatusFragments(t *testing.T) {
433		bin := auditBinary(t)
434		work := t.TempDir()
435		hash := mixedArtifactHash(t)
436		in := mixedCheckInput(hash)
437		in.Checks[0].ArtifactHash = "0" + strings.TrimPrefix(hash, hash[:1])
438		input := writeStructInput(t, work, "bad.json", in)
439		store := filepath.Join(work, "reports")
440	
441		stdout, _, code := runCLIAudit(t, bin, input, store)
442		if code == 0 {
443			t.Fatal("mismatched submission must fail")
444		}
445		for _, marker := range []string{"reportId", "findings", contractsentinel.StatusDefect, contractsentinel.StatusTimeout,
446			contractsentinel.StatusToolMissing, contractsentinel.StatusUnchecked, contractsentinel.StatusPass} {
447			if strings.Contains(stdout, marker) {
448				t.Fatalf("stdout must not leak a partial report fragment %q:\n%s", marker, stdout)
449			}
450		}
451	}
452	
453	// --- 已有报告时拒绝提交：不新增报告，也不改写已有内容 ---
454	
455	func TestCLIAuditImportChecksMismatchKeepsExistingReports(t *testing.T) {
456		bin := auditBinary(t)
457		work := t.TempDir()
458		store := filepath.Join(work, "reports")
459	
460		// 先落一份合法的混合状态报告。
461		good := writeStructInput(t, work, "good.json", mixedCheckInput(mixedArtifactHash(t)))
462		if _, stderr, code := runCLIAudit(t, bin, good, store); code != 0 {
463			t.Fatalf("valid setup audit must succeed: %s", stderr)
464		}
465		before, err := listFiles(store)
466		if err != nil {
467			t.Fatal(err)
468		}
469		if len(before) != 1 {
470			t.Fatalf("setup expected 1 report, got %v", before)
471		}
472		existingPath := filepath.Join(store, before[0])
473		existingBytes, err := os.ReadFile(existingPath)
474		if err != nil {
475			t.Fatal(err)
476		}
477	
478		// 再提交一份夹带哈希不匹配记录的提交。
479		badIn := mixedCheckInput(mixedArtifactHash(t))
480		badIn.Checks[2].ArtifactHash = strings.Repeat("b", 64)
481		bad := writeStructInput(t, work, "bad.json", badIn)
482		if _, _, code := runCLIAudit(t, bin, bad, store); code == 0 {
483			t.Fatal("invalid submission must exit non-zero")
484		}
485	
486		after, err := listFiles(store)
487		if err != nil {
488			t.Fatal(err)
489		}
490		if len(after) != len(before) || after[0] != before[0] {
491			t.Fatalf("rejected submission changed the store contents:\nbefore=%v\nafter=%v", before, after)
492		}
493		kept, err := os.ReadFile(existingPath)
494		if err != nil {
495			t.Fatal(err)
496		}
497		if !bytes.Equal(kept, existingBytes) {
498			t.Fatal("rejected submission modified the existing report bytes")
499		}
500	}
501	
502	// 读回标识必须是 64 位十六进制；此处顺手保证导出的标识形态稳定可用。
503	func TestCLIAuditImportChecksReportIDIsHexHash(t *testing.T) {
504		bin := auditBinary(t)
505		work := t.TempDir()
506		hash := mixedArtifactHash(t)
507		input := writeStructInput(t, work, "in.json", mixedCheckInput(hash))
508		store := filepath.Join(work, "reports")
509	
510		stdout, stderr, code := runCLIAudit(t, bin, input, store)
511		if code != 0 {
512			t.Fatalf("legal import must succeed, stderr=%s", stderr)
513		}
514		report := decodeReport(t, stdout)
515		if len(report.ReportID) != 64 {
516			t.Fatalf("report id length = %d, want 64", len(report.ReportID))
517		}
518		if _, err := hex.DecodeString(report.ReportID); err != nil {
519			t.Fatalf("report id must be hex: %v", err)
520		}
521	}
