290	// --- 合法字符串逐字保留：中文、换行与前后空格，source 是文本而非文件名 ---
291	
292	func TestParseAuditLegalArtifactStringsPreserved(t *testing.T) {
293		// source 即便长得像文件名，也只作为提交文本参与哈希，绝不按文件读取。
294		source := "  contract 金库 {\n // 中文注释 \n}\t"
295		abi := " [ { \"name\" : \"取款\" } ] "
296		bytecode := "  0x6080\n6040  "
297		in := artifactFieldsDoc(`"name":" 金库 Vault "`,
298			`"abi":`+jsonString(abi)+`,"bytecode":`+jsonString(bytecode)+`,"source":`+jsonString(source),
299			"")
300		artifact, _, _, _, err := ParseAuditInput([]byte(in))
301		if err != nil {
302			t.Fatalf("a legal submission with multilingual/whitespace text must parse: %v", err)
303		}
304		if artifact.Name != " 金库 Vault " || artifact.ABI != abi ||
305			artifact.Bytecode != bytecode || artifact.Source != source {
306			t.Fatalf("artifact text must be preserved verbatim:\n%+v", artifact)
307		}
308	
309		// 哈希与报告标识相对同样 Go 字段直接构造的结果保持原有值。
310		direct := Artifact{Name: " 金库 Vault ", ABI: abi, Bytecode: bytecode, Source: source}
311		if ArtifactHash(artifact) != ArtifactHash(direct) {
312			t.Fatal("the parsed artifact must hash exactly like the directly constructed one")
313		}
314		report := strictParsedReport(t, in)
315		if report.Artifact.Hash != ArtifactHash(direct) {
316			t.Fatalf("report must bind the original hash: %q", report.Artifact.Hash)
317		}
318	}
319	
320	// --- 缺失或 null 的 artifact 对象沿用既有“artifact name is required”判断 ---
321	
322	func TestParseAuditMissingArtifactObjectKeepsBusinessError(t *testing.T) {
323		for _, in := range []string{
324			`{"rules":[]}`,
325			`{"artifact":null,"rules":[]}`,
326		} {
327			a, rules, inv, checks, err := ParseAuditInput([]byte(in))
328			if err != nil {
329				t.Fatalf("a missing/null artifact object parses with defaults as before: %v", err)
330			}
331			if _, err := BuildReport(a, rules, inv, checks); err == nil ||
332				!strings.Contains(err.Error(), "artifact name is required") {
333				t.Fatalf("missing artifact must keep the existing required-name error: %v", err)
334			}
335		}
336	}
